// Runs the test suite once per near-miss copy with the loader hook; lib/ is never written.
import { spawnSync } from 'node:child_process'
import { readdirSync } from 'node:fs'

const dir = '.team/near-miss'
let survivors = 0
for (const name of readdirSync(dir).filter(n => /^\d\d-.*\.mjs$/.test(n)).sort()) {
  const r = spawnSync(process.execPath, ['--import', '/tmp/nm/register.mjs', '--test', 'test/*.test.mjs'], {
    env: { ...process.env, NEAR_MISS: `${dir}/${name}`, NODE_OPTIONS: '--import /tmp/nm/register.mjs' },
    encoding: 'utf8',
  })
  const caught = r.status !== 0
  if (!caught) survivors++
  console.log(caught ? 'CAUGHT' : 'SURVIVED', name)
}
console.log('survivors:', survivors)

