// Redirects lib/<name>.mjs to the near-miss copy named in NEAR_MISS (e.g. .team/near-miss/05-import.mjs).
// Relative imports inside the copy resolve as if it lived in lib/.
import { basename, resolve } from 'node:path'
import { pathToFileURL } from 'node:url'

const copy = resolve(process.env.NEAR_MISS)
const target = pathToFileURL(resolve('lib', basename(copy).replace(/^(\d\d|control)-/, ''))).href
const replacement = pathToFileURL(copy).href

export async function resolve_(specifier, context, next) {
  const parentURL = context.parentURL === replacement ? target : context.parentURL
  const result = await next(specifier, { ...context, parentURL })
  return result.url === target ? { ...result, url: replacement } : result
}
export { resolve_ as resolve }

